<script setup lang="ts">import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{api}from'../../api';import{useSessionStore}from'../../stores/session';import type{StaffProfile}from'../../types';const session=useSessionStore(),profile=ref<StaffProfile>();onShow(async()=>profile.value=await api.profile(session.role))</script>
<template><view v-if="profile" class="page profile"><view class="profile-card"><view class="person"><view class="avatar"><text>{{profile.name.slice(0,1)}}</text><view class="avatar__dot"></view></view><view><text class="name">{{profile.name}}</text><text class="staff">{{profile.roleText}} · {{profile.staffNo}}</text></view></view><view class="badge">优秀履约员</view></view><view class="kpi card"><view><text>96%</text><text>准时率</text></view><view><text>99%</text><text>凭证完整率</text></view><view><text>286</text><text>累计配送</text></view></view><view class="section-title"><view><text class="kicker">ACCOUNT</text><text class="section-title__main">履约设置</text></view></view><view class="menu card"><view role="button" @tap="uni.navigateTo({url:'/pages/leave/index'})"><view class="menu__icon calendar"></view><view class="menu__body"><text>请假与跨楼调配</text><text>排班、请假、接受临时调配</text></view><text class="arrow">→</text></view><view><view class="menu__icon building"></view><view class="menu__body"><text>服务楼栋</text><text>{{profile.building}}</text></view><text class="arrow">→</text></view><view><view class="menu__icon pulse"></view><view class="menu__body"><text>工作状态</text><text>{{profile.online?'当前可接收新任务':'暂不接单'}}</text></view><text class="online-text">{{profile.online?'在线':'休息'}}</text></view><view><view class="menu__icon help"></view><view class="menu__body"><text>履约规范与帮助</text><text>标准流程与常见问题</text></view><text class="arrow">→</text></view></view><view class="service"><text>履约支持</text><strong>09:00—22:30</strong></view></view></template>
<style scoped lang="scss">@import '../../styles/theme.scss';.profile{padding-top:42rpx;background:radial-gradient(circle at 80% 5%,rgba(185,242,39,.27),transparent 28%),linear-gradient(180deg,#dcefe2 0,$paper 520rpx)}.profile-card{display:flex;justify-content:space-between;align-items:center;padding:32rpx;border-radius:34rpx;background:$primary-dark;color:#fff}.person{display:flex;align-items:center;gap:20rpx}.avatar{position:relative;width:104rpx;height:104rpx;border-radius:30rpx;background:$lime;color:$primary-dark;display:grid;place-items:center;font-size:45rpx;font-weight:900}.avatar__dot{position:absolute;right:-5rpx;bottom:-5rpx;width:23rpx;height:23rpx;border:5rpx solid $primary-dark;background:$primary;border-radius:50%}.name,.staff{display:block}.name{font-size:38rpx;font-weight:900}.staff{font-size:20rpx;opacity:.65;margin-top:3rpx}.badge{padding:8rpx 14rpx;border-radius:999rpx;background:rgba(185,242,39,.14);color:$lime;font-size:18rpx;font-weight:800}.kpi{display:grid;grid-template-columns:repeat(3,1fr);margin:22rpx 0;padding:25rpx 6rpx;text-align:center}.kpi>view+view{border-left:2rpx solid $line}.kpi text{display:block}.kpi text:first-child{font-size:31rpx;font-weight:900;color:$primary-dark}.kpi text:last-child{font-size:18rpx;color:$muted;margin-top:4rpx}.kicker{display:block;color:$primary;font-size:18rpx;font-weight:900;letter-spacing:3rpx}.menu{padding:2rpx 24rpx}.menu>view{min-height:124rpx;display:flex;align-items:center;gap:18rpx;border-bottom:2rpx solid $line}.menu>view:last-child{border-bottom:none}.menu__icon{width:64rpx;height:64rpx;border-radius:19rpx;background:$soft;position:relative}.calendar:before,.building:before,.pulse:before,.help:before{position:absolute;inset:0;display:grid;place-items:center;color:$primary-dark;font-size:24rpx;font-weight:900}.calendar:before{content:"31"}.building:before{content:"5F"}.pulse:before{content:"ON"}.help:before{content:"?"}.menu__body{flex:1}.menu__body text{display:block}.menu__body text:first-child{font-weight:800}.menu__body text:last-child{font-size:19rpx;color:$muted;margin-top:3rpx}.arrow{color:$muted}.online-text{color:$primary;font-size:22rpx;font-weight:900}.service{display:flex;justify-content:space-between;margin-top:22rpx;padding:24rpx 8rpx;color:$muted;font-size:21rpx}.service strong{color:$primary-dark}</style>
